package vn.somehouse;
import jakarta.servlet.http.HttpServletRequest;import org.slf4j.*;import org.springframework.dao.*;import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;import org.springframework.web.method.annotation.HandlerMethodValidationException;import org.springframework.web.multipart.MaxUploadSizeExceededException;import org.springframework.http.converter.HttpMessageNotReadableException;import java.net.URI;import java.util.*;
@org.springframework.core.annotation.Order(org.springframework.core.Ordered.HIGHEST_PRECEDENCE) @RestControllerAdvice public class ApiErrors {private final Logger log=LoggerFactory.getLogger(getClass());
 static ProblemDetail problem(HttpStatus status,String code,String message,HttpServletRequest req){ProblemDetail p=ProblemDetail.forStatusAndDetail(status,message);p.setTitle(status.getReasonPhrase());p.setType(URI.create("urn:somehouse:error:"+code.toLowerCase(Locale.ROOT)));p.setProperty("code",code);p.setProperty("requestId",req.getAttribute("requestId"));return p;}
 @ExceptionHandler(ApiException.class) ResponseEntity<ProblemDetail> app(ApiException e,HttpServletRequest r){return ResponseEntity.status(e.status).body(problem(e.status,e.code,e.getMessage(),r));}
 @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<ProblemDetail> validation(MethodArgumentNotValidException e,HttpServletRequest r){var p=problem(HttpStatus.BAD_REQUEST,"VALIDATION_ERROR","Vui lòng kiểm tra thông tin đã nhập.",r);Map<String,String> errors=new LinkedHashMap<>();e.getBindingResult().getFieldErrors().forEach(x->errors.putIfAbsent(x.getField(),x.getDefaultMessage()));p.setProperty("errors",errors);return ResponseEntity.badRequest().body(p);}
 @ExceptionHandler({HttpMessageNotReadableException.class,HandlerMethodValidationException.class,IllegalArgumentException.class}) ResponseEntity<ProblemDetail> bad(Exception e,HttpServletRequest r){return ResponseEntity.badRequest().body(problem(HttpStatus.BAD_REQUEST,"VALIDATION_ERROR","Dữ liệu hoặc tham số không hợp lệ.",r));}
 @ExceptionHandler(DataIntegrityViolationException.class) ResponseEntity<ProblemDetail> duplicate(Exception e,HttpServletRequest r){return ResponseEntity.status(409).body(problem(HttpStatus.CONFLICT,"DATA_CONFLICT","Đường dẫn đã tồn tại hoặc dữ liệu đang được sử dụng.",r));}
 @ExceptionHandler(MaxUploadSizeExceededException.class) ResponseEntity<ProblemDetail> large(Exception e,HttpServletRequest r){return ResponseEntity.status(413).body(problem(HttpStatus.PAYLOAD_TOO_LARGE,"UPLOAD_TOO_LARGE","Ảnh phải nhỏ hơn 5 MB.",r));}
 @ExceptionHandler(DataAccessException.class) ResponseEntity<ProblemDetail> database(Exception e,HttpServletRequest r){log.error("Database request failed, requestId={}",r.getAttribute("requestId"),e);return ResponseEntity.status(503).header("Retry-After","3").body(problem(HttpStatus.SERVICE_UNAVAILABLE,"DATABASE_UNAVAILABLE","Chưa kết nối được cơ sở dữ liệu. Vui lòng thử lại.",r));}
 @ExceptionHandler(Exception.class) ResponseEntity<ProblemDetail> unexpected(Exception e,HttpServletRequest r){if(e instanceof org.springframework.web.ErrorResponse response){var status=HttpStatus.resolve(response.getStatusCode().value());if(status!=null&&status.is4xxClientError())return ResponseEntity.status(status).body(problem(status,status==HttpStatus.NOT_FOUND?"NOT_FOUND":"REQUEST_ERROR",status==HttpStatus.NOT_FOUND?"Không tìm thấy địa chỉ yêu cầu.":"Yêu cầu không hợp lệ.",r));}log.error("Unhandled request, requestId={}",r.getAttribute("requestId"),e);return ResponseEntity.internalServerError().body(problem(HttpStatus.INTERNAL_SERVER_ERROR,"INTERNAL_ERROR","Chưa xử lý được yêu cầu. Vui lòng thử lại.",r));}
}
